referenceSolutions.javascript:
export function cloneGraph(adjacency            , edits            )                                              {
  const copies            =[]; for(const neighbors of adjacency)copies.push(neighbors.map(label=>label)); for(const [node,label] of edits)copies[node-1].push(label); return {original:adjacency,clone:copies};
}

